     1→import {ChainForkConfig} from "@lodestar/config";
     2→import {isForkPostDeneb, isForkPostFulu} from "@lodestar/params";
     3→import {DataAvailabilityStatus, computeTimeAtSlot} from "@lodestar/state-transition";
     4→import {UintNum64, deneb} from "@lodestar/types";
     5→import {ErrorAborted, Logger} from "@lodestar/utils";
     6→import {Metrics} from "../../metrics/metrics.js";
     7→import {BlockError, BlockErrorCode} from "../errors/index.js";
     8→import {validateBlobSidecars} from "../validation/blobSidecar.js";
     9→import {validateDataColumnsSidecars} from "../validation/dataColumnSidecar.js";
    10→import {
    11→  BlobSidecarValidation,
    12→  BlockInput,
    13→  BlockInputAvailableData,
    14→  BlockInputBlobs,
    15→  BlockInputDataColumns,
    16→  BlockInputType,
    17→  ImportBlockOpts,
    18→  getBlockInput,
    19→} from "./types.js";
    20→
    21→// we can now wait for full 12 seconds because unavailable block sync will try pulling
    22→// the blobs from the network anyway after 500ms of seeing the block
    23→const BLOB_AVAILABILITY_TIMEOUT = 12_000;
    24→
    25→/**
    26→ * Verifies some early cheap sanity checks on the block before running the full state transition.
    27→ *
    28→ * - Parent is known to the fork-choice
    29→ * - Check skipped slots limit
    30→ * - check_block_relevancy()
    31→ *   - Block not in the future
    32→ *   - Not genesis block
    33→ *   - Block's slot is < Infinity
    34→ *   - Not finalized slot
    35→ *   - Not already known
    36→ */
    37→export async function verifyBlocksDataAvailability(
    38→  chain: {config: ChainForkConfig; genesisTime: UintNum64; logger: Logger; metrics: Metrics | null},
    39→  blocks: BlockInput[],
    40→  signal: AbortSignal,
    41→  opts: ImportBlockOpts
    42→): Promise<{
    43→  dataAvailabilityStatuses: DataAvailabilityStatus[];
    44→  availableTime: number;
    45→  availableBlockInputs: BlockInput[];
    46→}> {
    47→  const lastBlock = blocks.at(-1);
    48→  if (!lastBlock) {
    49→    throw Error("Empty partiallyVerifiedBlocks");
    50→  }
    51→
    52→  const dataAvailabilityStatuses: DataAvailabilityStatus[] = [];
    53→  const seenTime = opts.seenTimestampSec !== undefined ? opts.seenTimestampSec * 1000 : Date.now();
    54→
    55→  const availableBlockInputs: BlockInput[] = [];
    56→
    57→  for (const blockInput of blocks) {
    58→    if (signal.aborted) {
    59→      throw new ErrorAborted("verifyBlocksDataAvailability");
    60→    }
    61→    // Validate status of only not yet finalized blocks, we don't need yet to propogate the status
    62→    // as it is not used upstream anywhere
    63→    const {dataAvailabilityStatus, availableBlockInput} = await maybeValidateBlobs(chain, blockInput, signal, opts);
    64→    dataAvailabilityStatuses.push(dataAvailabilityStatus);
    65→    availableBlockInputs.push(availableBlockInput);
    66→  }
    67→
    68→  const availableTime = lastBlock.type === BlockInputType.dataPromise ? Date.now() : seenTime;
    69→  if (blocks.length === 1 && opts.seenTimestampSec !== undefined && blocks[0].type !== BlockInputType.preData) {
    70→    const recvToAvailableTime = availableTime / 1000 - opts.seenTimestampSec;
    71→    const numBlobs = (blocks[0].block as deneb.SignedBeaconBlock).message.body.blobKzgCommitments.length;
    72→
    73→    chain.metrics?.gossipBlock.receivedToBlobsAvailabilityTime.observe({numBlobs}, recvToAvailableTime);
    74→    chain.logger.verbose("Verified blobs availability", {
    75→      slot: blocks[0].block.message.slot,
    76→      recvToAvailableTime,
    77→      type: blocks[0].type,
    78→    });
    79→  }
    80→
    81→  return {dataAvailabilityStatuses, availableTime, availableBlockInputs};
    82→}
    83→
    84→async function maybeValidateBlobs(
    85→  chain: {config: ChainForkConfig; genesisTime: UintNum64; metrics: Metrics | null; logger: Logger},
    86→  blockInput: BlockInput,
    87→  signal: AbortSignal,
    88→  opts: ImportBlockOpts
    89→): Promise<{dataAvailabilityStatus: DataAvailabilityStatus; availableBlockInput: BlockInput}> {
    90→  switch (blockInput.type) {
    91→    case BlockInputType.preData:
    92→      return {dataAvailabilityStatus: DataAvailabilityStatus.PreData, availableBlockInput: blockInput};
    93→
    94→    case BlockInputType.outOfRangeData:
